import { CHANNELS, normalize, aggregate, benchmark, buildPlan, flowExport, csvText,
  historicalRows, summarizeLedger, historicalSeries } from './engine.js';

const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (v, d = 0) => v == null ? '—' : new Intl.NumberFormat('es-CO', {maximumFractionDigits:d}).format(v);
const money = v => v == null ? '—' : '$' + num(v);
const pct = v => v == null ? '—' : num(v * 100, 1) + '%';
const month = m => new Date(m + '-15T12:00:00Z').toLocaleDateString('es-CO', {month:'short',year:'numeric',timeZone:'America/Bogota'}).replace('.', '');
const CITY = {BTA:'Bogotá', MDE:'Medellín'};
const REGION = {BTA:'Bogotá y Sabana', MDE:'Medellín y Antioquia'};
const MEDIA = {...CHANNELS, youtube:{name:'YouTube',short:'YouTube',color:'#dc5252'},other:{name:'Otros / sin clasificar',short:'Otros',color:'#9ba4ab'}};
const paths = {arrow:'M5 12h14m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M18 6 6 18',
  grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chart:'M3 3v18h18M7 15l4-5 4 2 5-7',
  flow:'M5 6h14M5 12h9M5 18h14',code:'m7 7-5 5 5 5m10-10 5 5-5 5m-4-13-3 19',
  search:'M15 15l6 6M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
  copy:'M8 8h12v13H8zM16 8V3H3v13h5',save:'M5 3h12l4 4v14H3V3Zm2 0v6h9V3M7 21v-8h10v8',
  info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z',
  calendar:'M3 5h18v16H3zM7 2v6m10-6v6M3 11h18',folder:'M3 7V3h7l3 4h8v14H3Z',external:'M14 3h7v7M21 3l-12 12m1-12H3v18h18v-7',building:'M4 21V7l9-4v18m0-12h7v12M2 21h20M7 8v2m3-3v2m-3 4v2m3-3v2m6-2v2m0 3v2'};
const icon = name => `<svg viewBox="0 0 24 24" class="icon" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.grid}"/></svg>`;
const mark = c => `<span class="media-mark ${c}" aria-hidden="true">${({meta:'∞',google:'G',tiktok:'♪',youtube:'▶',other:'•'})[c]}</span>`;
const opts = (items, value) => items.map(([id,label]) => `<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const empty = (title, text) => `<div class="empty">${icon('building')}<h3>${title}</h3><p>${text}</p></div>`;
const defaultConfig = city => ({city,title:`${CITY[city]} · Noviembre 2026`,budget:0,includesTax:false,taxRate:19,startDate:'2026-11-01',endDate:'2026-11-30',historyStart:'2026-07',historyEnd:'2026-09',weighting:'uniform',selected:[],channels:['meta','google','tiktok'],allocation:'historical',mix:'historical',priorities:{},overrides:{},scenario:'base',sensitivity:20,frequency:3.1,namingMode:'new',stage:'auto',suffix:'',example:false});
const views = ['summary','builder','history','names','method','saved'];
let data, config, plan, timer, searchTimer;
let city = 'BTA', view = views.includes(location.hash.slice(1)) ? location.hash.slice(1) : 'summary';
let step = 1, historyTab = 'months', historySearch = '', historyChannel = 'all', historyProject = 'all';
let period = {start:'2025-02',end:'2026-10'};
let filter = {search:'',kind:'all',active:true,selected:false};
let cityDrafts = {}, localReady = true;
try {city = localStorage.getItem('capital-flow-city-v2') === 'MDE' ? 'MDE' : 'BTA'; cityDrafts=JSON.parse(localStorage.getItem('capital-flow-drafts-v2') || '{}');} catch {localReady=false;}

function sanitize(input, forcedCity) {
  const c = forcedCity || (input?.city === 'MDE' ? 'MDE' : 'BTA'), clean = defaultConfig(c);
  if (!input || typeof input !== 'object') return clean;
  for (const k of Object.keys(clean)) if (input[k] !== undefined) clean[k] = input[k];
  clean.city=c;
  clean.selected=Array.isArray(input.selected)?[...new Set(input.selected)].filter(id=>data.projects.some(p=>p.id===id&&p.city===c)):[];
  clean.channels=Array.isArray(input.channels)?[...new Set(input.channels)].filter(id=>CHANNELS[id]):clean.channels;
  clean.title=String(clean.title).slice(0,100); clean.suffix=String(clean.suffix).slice(0,30);
  for (const k of ['budget','taxRate','sensitivity','frequency']) {clean[k]=Number(clean[k]);if(!Number.isFinite(clean[k])||clean[k]<0)throw Error('Revisa los valores numéricos.');}
  for (const k of ['startDate','endDate','historyStart','historyEnd']) if(typeof clean[k]!=='string')throw Error('Revisa las fechas.');
  if (!clean.priorities || typeof clean.priorities!=='object')clean.priorities={};
  if (!clean.overrides || typeof clean.overrides!=='object')clean.overrides={};
  return clean;
}
function persist(){cityDrafts[city]=structuredClone(config);try{localStorage.setItem('capital-flow-drafts-v2',JSON.stringify(cityDrafts));localStorage.setItem('capital-flow-city-v2',city);localReady=true;}catch{localReady=false;}}
function toast(text){clearTimeout(timer);$('#toast').textContent=text;$('#toast').classList.add('show');timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function download(text,name,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado.');}catch{toast('No se pudo copiar. Puedes seleccionar la nomenclatura.');}}
function nav(next){view=next;location.hash=next;render();window.scrollTo({top:0,behavior:'smooth'});}
function update(patch){config={...config,...patch};persist();render();}
function switchCity(next){if(next===city)return;persist();city=next;config=sanitize(cityDrafts[city],city);step=1;filter={search:'',kind:'all',active:true,selected:false};historyProject='all';historySearch='';historyChannel='all';persist();render();}
function historyRows(filtered=false){return historicalRows(data,{city,...period,...(filtered?{channel:historyChannel,project:historyProject,search:historySearch}:{})});}
function cityProjects(){return data.projects.filter(p=>p.city===city);}
function visibleProjects(){return cityProjects().filter(p=>(!filter.active||p.active)&&(filter.kind==='all'||p.kind===filter.kind)&&(!filter.selected||config.selected.includes(p.id))&&(!filter.search||normalize(p.name+' '+p.zone).includes(normalize(filter.search))));}
function rangeLabel(){return `${month(period.start)} — ${month(period.end)}`;}
function pageHead(kicker,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function header(){return `<aside class="sidebar"><a class="sidebar-brand" href="#summary" aria-label="Capital Flow, inicio"><img src="./capital-logo.svg" alt="Constructora Capital"><span>F L O W</span></a><nav aria-label="Navegación principal">${[['summary','grid','Resumen'],['projects','building','Proyectos'],['builder','chart','Mi flow'],['names','code','Nomenclaturas'],['history','calendar','Histórico']].map(([id,ic,label])=>`<button ${id==='projects'?'data-open-projects':`data-view="${id}"`} class="${id==='projects'&&view==='builder'&&step===1||id===view&&!(id==='builder'&&step===1)?'active':''}" ${id===view?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button data-view="saved">${icon('folder')}Flows guardados</button><button data-view="method">${icon('info')}Fuentes y fórmulas</button><span>Capital Flow · Planeación de medios</span></div></aside><header class="workspace-topbar"><div class="city-switch" role="group" aria-label="Ciudad del espacio de trabajo">${icon('pin')}${Object.entries(CITY).map(([id,label])=>`<button data-city="${id}" class="${city===id?'active':''}" aria-pressed="${city===id}">${label}</button>`).join('')}</div><div class="header-actions">${view==='builder'?`<span class="top-dates">${icon('calendar')}${formatDate(config.startDate)} <span>–</span> ${formatDate(config.endDate)}</span><button class="button" data-action="save">${icon('save')}Guardar flow</button><button class="button gold" data-action="export" data-export-button ${plan.errors.length?'disabled':''}>${icon('download')}Exportar</button>`:`<span class="snapshot"><i></i>Corte 19 oct 2026</span><button class="button gold" data-new-flow>Crear flow ${icon('plus')}</button>`}</div></header>`;}
function formatDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(value+'T12:00:00Z').toLocaleDateString('es-CO',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/Bogota'}).replace('.',''):'Sin fecha';}
function heroProjects(){const chosen=config.selected.map(id=>data.projects.find(p=>p.id===id&&p.city===city)).filter(p=>p?.image);const preferred=(city==='BTA'?['BTA-ELEMENT142','BTA-NUVO','BTA-MISTRAL','BTA-VERDI']:['MDE-PUERTOCAPRI','MDE-ENTREBOSQUES','MDE-NATUREAQUA','MDE-BOSQUEROSA']).map(id=>data.projects.find(p=>p.id===id)).filter(p=>p?.image);return (chosen.length?chosen:preferred).slice(0,4);}
function flowHero(title='Tu próximo flow, <em>listo.</em>',summary=false){const projects=heroProjects();return `<section class="flow-hero"><div class="hero-mosaic" style="--photo-count:${projects.length}">${projects.map(p=>`<figure><img src="${esc(p.image)}" alt="${esc(p.name)}, imagen oficial del proyecto"><figcaption>${esc(p.name)}</figcaption></figure>`).join('')}</div><div class="flow-hero-copy"><h1>${title}</h1><p>${CITY[city]} · ${summary?'Tu inversión a la vista':esc(config.title.replace(new RegExp('^'+CITY[city]+'[ ·—-]*'),'')||'Nuevo plan de medios')}</p>${summary?`<button class="hero-status" data-action="example">${icon('flow')}Probar el flow de la referencia ${icon('arrow')}</button>`:`<span class="hero-status">${icon('info')}${config.example?'Simulación de ejemplo':'Proyección basada en históricos'}</span>`}</div></section>`;}

function periodBar(){return `<div class="period-bar"><div class="period-heading">${icon('calendar')}<strong>Periodo del histórico</strong><span>Toda ${CITY[city]} · todos los proyectos</span></div><div class="period-options">${[['all','Todo el histórico'],['2026','2026'],['2025','2025'],['last','Septiembre 2026']].map(([id,label])=>`<button data-period="${id}" class="${id==='all'&&period.start==='2025-02'&&period.end==='2026-10'||id==='2026'&&period.start==='2026-02'&&period.end==='2026-10'||id==='2025'&&period.start==='2025-02'&&period.end==='2025-12'||id==='last'&&period.start==='2026-09'&&period.end==='2026-09'?'active':''}">${label}</button>`).join('')}</div><div class="period-dates"><label><span>Desde</span><input type="month" data-period-field="start" min="2025-02" max="2026-10" value="${period.start}" aria-label="Histórico desde"></label><span>→</span><label><span>Hasta</span><input type="month" data-period-field="end" min="2025-02" max="2026-10" value="${period.end}" aria-label="Histórico hasta"></label></div></div>`;}
function historicalKpis(s,rows=historyRows()){
  const days=[...new Set(rows.map(r=>r[1]))].reduce((total,m)=>total+(m==='2026-10'?19:new Date(Number(m.slice(0,4)),Number(m.slice(5,7)),0).getDate()),0);
  return `<div class="metrics historical-metrics"><article class="metric"><span>${icon('chart')}Inversión real registrada <small>COP</small></span><strong>${money(s.actual)}</strong><p>Consolidado completo · ${numberRows(s.rows)}</p></article><article class="metric"><span>${icon('calendar')}Inversión planeada <small>COP</small></span><strong>${money(s.planned)}</strong><p>${pct(s.execution)} ejecutado</p></article><article class="metric"><span>${icon('building')}Leads y conversiones</span><strong>${num(s.leads,1)}</strong><p>Campañas elegibles de leads</p></article><article class="metric"><span>${icon('flow')}CPL del histórico <small>COP</small></span><strong>${money(s.cpl)}</strong><p>Inversión de leads ÷ leads</p></article></div><div class="secondary-metrics history-secondary"><div><span>Impresiones</span><strong>${num(s.impressions)}</strong></div><div><span>Clics</span><strong>${num(s.clicks)}</strong></div><div><span>Gasto diario promedio</span><strong>${money(days?s.actual/days:null)}</strong></div><div><span>CPM</span><strong>${money(s.impressions?s.actual/s.impressions*1000:null)}</strong></div><div><span>CPC</span><strong>${money(s.clicks?s.actual/s.clicks:null)}</strong></div><div><span>CTR</span><strong>${pct(s.impressions?s.clicks/s.impressions:null)}</strong></div><div><span>Alcance único</span><strong class="not-reported">No reportado</strong></div></div><p class="daily-note">Promedio diario sobre los meses con registros${period.end==='2026-10'?' · octubre hasta el día 19':''}.</p>`;
}

function numberRows(n){return `${num(n)} filas del consolidado`;}
function sourceNote(rows){const s=data.meta.consolidated[city], partial=period.start<='2026-10'&&period.end>='2026-10';return `<div class="source-note">${icon('info')}<p><strong>${esc(s.sheet.trim())}</strong> · ${rangeLabel()}. ${partial?'Octubre parcial: corte al 19. ':''}Los totales incluyen marca y campañas sin proyecto asignado. ${rows.length!==historyRows().length?'Hay filtros adicionales en esta vista. ':''}<button data-view="method">Ver conciliación y alcance</button></p></div>`;}
function chart(rows){const series=historicalSeries(rows);if(!series.length)return empty('Sin registros en este periodo','Prueba otro intervalo. Un mes sin registros no equivale a inversión cero.');const max=Math.max(...series.flatMap(s=>[s.actual,s.planned]),1),w=1000,h=260,left=64,right=18,top=20,bottom=42,bw=(w-left-right)/series.length;return `<div class="chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Inversión planeada y real por mes en ${CITY[city]}. Los valores exactos están en la tabla del histórico.">${[0,.25,.5,.75,1].map(v=>{const y=top+(h-top-bottom)*(1-v);return `<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#e9edf0"/><text x="${left-12}" y="${y+4}" text-anchor="end" class="chart-axis">${num(max*v/1000000,0)} M</text>`;}).join('')}${series.map((s,i)=>{const x=left+i*bw+bw*.18,width=bw*.27,base=h-bottom;return `<g><title>${month(s.month)}: real ${money(s.actual)}; planeada ${money(s.planned)}</title><rect x="${x}" y="${base-s.planned/max*(h-top-bottom)}" width="${width}" height="${s.planned/max*(h-top-bottom)}" rx="3" fill="#dce1e6"/><rect x="${x+width+3}" y="${base-s.actual/max*(h-top-bottom)}" width="${width}" height="${s.actual/max*(h-top-bottom)}" rx="3" fill="${s.month==='2026-10'?'#e2b600':'#174a96'}"/><text x="${left+i*bw+bw/2}" y="${base+21}" text-anchor="middle" class="chart-axis">${series.length>12?s.month.slice(5)+'/'+s.month.slice(2,4):month(s.month)}</text></g>`;}).join('')}</svg></div>`;}
function channelBreakdown(rows){const total=summarizeLedger(rows).actual;return `<div class="channel-list">${Object.entries(MEDIA).map(([id,c])=>{const s=summarizeLedger(rows.filter(r=>r[4]===id));if(!s.actual&&!s.planned)return '';return `<div class="channel-item"><div>${mark(id)}<strong>${c.short}</strong><span>${pct(total?s.actual/total:0)}</span><b>${money(s.actual)}</b></div><div class="track"><i style="width:${Math.min(100,total?s.actual/total*100:0)}%;background:${c.color}"></i></div></div>`;}).join('')}</div>`;}
function summaryView(){const rows=historyRows(),s=summarizeLedger(rows);return `${flowHero('El pulso de <em>'+CITY[city]+'.</em>',true)}<div class="workspace-surface summary-surface">${periodBar()}<div class="scope-line"><span>${rangeLabel()}</span><strong>Consolidado completo de ${CITY[city]}</strong></div>${historicalKpis(s,rows)}<div class="overview-grid"><section class="panel evolution"><div class="panel-head"><div><span class="eyebrow">INVERSIÓN MENSUAL</span><h2>Planeado y ejecutado</h2></div><div class="legend"><span><i class="planned"></i>Planeada</span><span><i class="actual"></i>Real</span></div></div>${chart(rows)}<div class="chart-foot"><span>${s.months} meses con registros · los eneros no figuran en estas hojas</span><button class="text-button" data-view="history">Ver cifras exactas ${icon('arrow')}</button></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">DISTRIBUCIÓN REAL</span><h2>Inversión por medio</h2></div></div>${channelBreakdown(rows)}</section></div>${sourceNote(rows)}<section class="start-strip"><div><span class="eyebrow">TU PRÓXIMO FLOW</span><h2>Del histórico al próximo resultado.</h2><p>Elige proyectos, distribuye la inversión y ajusta el plan en vivo.</p></div><button class="button gold" data-new-flow>Elegir proyectos ${icon('arrow')}</button></section></div>`;}

function projectCard(p){const selected=config.selected.includes(p.id),s=aggregate(data.records.filter(r=>r[0]===p.id&&r[2]>=config.historyStart&&r[2]<=config.historyEnd&&config.channels.includes(r[1])));return `<article class="project-card ${selected?'selected':''}"><button class="project-image" data-project="${p.id}" aria-pressed="${selected}" aria-label="${selected?'Quitar':'Seleccionar'} ${esc(p.name)}">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy">`:`<span class="placeholder">${icon('building')}<span>Proyecto histórico</span></span>`}<span class="project-badge">${p.kind}</span><span class="select-circle">${icon(selected?'check':'plus')}</span></button><div class="project-copy"><div class="project-location">${icon('pin')}${esc(p.zone||REGION[p.city])}</div><h3><button data-project="${p.id}">${esc(p.name)}</button>${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noreferrer" aria-label="Ver ${esc(p.name)} en su sitio oficial">${icon('external')}</a>`:''}</h3><div class="project-bottom"><div><span>CPL histórico de leads</span><strong>${money(s.cpl)}</strong></div><div class="project-media">${Object.keys(CHANNELS).filter(c=>data.records.some(r=>r[0]===p.id&&r[1]===c&&r[2]>=config.historyStart&&r[2]<=config.historyEnd)).map(mark).join('')}</div></div><p class="project-period">${month(config.historyStart)} — ${month(config.historyEnd)}${s.months?'':' · sin registros propios'}</p></div></article>`;}
function stepper(){return `<div class="stepper" aria-label="Pasos para crear el flow">${['Proyectos','Presupuesto','Revisión'].map((title,i)=>`<button data-step="${i+1}" class="${step===i+1?'active':''} ${step>i+1?'completed':''}" aria-current="${step===i+1?'step':'false'}"><span>${step>i+1?icon('check'):i+1}</span><strong>${i+1}. ${title}</strong>${i<2?icon('arrow'):''}</button>`).join('')}</div>`;}

function selectionView(){const visible=visibleProjects();return `<div class="project-toolbar"><label class="search-field">${icon('search')}<input id="project-search" value="${esc(filter.search)}" placeholder="Buscar proyecto o zona" aria-label="Buscar proyectos"></label><div class="chips">${[['all','Todos'],['VIS','VIS'],['NO VIS','No VIS']].map(([id,label])=>`<button data-kind="${id}" class="${filter.kind===id?'active':''}">${label}</button>`).join('')}</div><label class="check"><input id="active-filter" type="checkbox" ${filter.active?'checked':''}>Flow de octubre</label><label class="check"><input id="selected-filter" type="checkbox" ${filter.selected?'checked':''}>Seleccionados</label></div><div class="list-heading"><p><strong>${visible.length}</strong> proyectos de ${CITY[city]}</p><div><button class="text-button" data-action="select-visible">Seleccionar visibles</button><button class="text-button muted" data-action="clear">Limpiar</button></div></div><div class="project-grid">${visible.map(projectCard).join('')}</div>${visible.length?'':empty('No hay proyectos con estos filtros','Cambia la búsqueda o activa el catálogo completo.')}<div class="selection-dock"><div class="selected-thumbs">${cityProjects().filter(p=>config.selected.includes(p.id)&&p.image).slice(0,4).map(p=>`<img src="${esc(p.image)}" alt="${esc(p.name)}">`).join('')}</div><div><strong>${config.selected.length} proyectos seleccionados</strong><span>Flow exclusivo de ${CITY[city]}</span></div><button class="button dark" data-step="2" ${!config.selected.length?'disabled':''}>Definir presupuesto ${icon('arrow')}</button></div>`;}
function latestBudget(){return data.ledger.filter(r=>r[0]===city&&r[1]==='2026-10'&&config.selected.includes(r[2])&&config.channels.includes(r[4])).reduce((s,r)=>s+(r[6]||0),0);}
function projectionMini(){return `<div class="forecast-panel"><div class="eyebrow">PROYECCIÓN / ${CITY[city].toUpperCase()}</div><h2>Así se ve tu plan.</h2><span class="forecast-main">${plan.rows.length?num(plan.results):'—'}<small>leads y conversiones estimados</small></span><div class="forecast-numbers"><div><span>Inversión neta</span><strong>${money(plan.net)}</strong></div><div><span>CPL proyectado</span><strong>${money(plan.cpl)}</strong></div><div><span>Duración</span><strong>${plan.days} días</strong></div><div><span>Inversión diaria</span><strong>${plan.daily?money(plan.daily):'—'}</strong></div></div><div class="forecast-mix">${Object.entries(CHANNELS).map(([id,c])=>{const budget=plan.rows.filter(r=>r.channel===id).reduce((s,r)=>s+r.budget,0);return `<div>${mark(id)}<span>${c.short}</span><strong>${money(budget)}</strong></div>`;}).join('')}</div><p>Estimación lineal a partir del consolidado de ${CITY[city]}. Ajusta el CPL si tienes una expectativa diferente.</p>${plan.errors.length?`<ul class="input-errors">${plan.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`:''}<button class="button gold full" data-step="3" ${plan.errors.length?'disabled':''}>Generar mi flow ${icon('arrow')}</button></div>`;}
function budgetView(){return `<div class="flow-workspace">${flowControls()}<div class="flow-main"><div id="live-kpis">${planKpis()}</div><section class="panel allocation-panel"><div class="panel-head"><div><h2>Distribuye tu inversión</h2><p>Mueve los controles y el flow se recalcula al instante.</p></div></div><div class="allocation-options"><label>Entre proyectos<select data-config="allocation">${opts([['historical','Según inversión histórica'],['equal','Reparto equitativo'],['manual','Personalizar pesos']],config.allocation)}</select></label><label>Entre medios<select data-config="mix">${opts([['historical','Mix histórico'],['equal','Mix equitativo']],config.mix)}</select></label></div><div class="allocation-list">${allocationRows()}</div><div class="allocation-footer"><span>Los pesos se normalizan para repartir el 100% del presupuesto.</span><button class="button gold" data-step="3" id="generate-flow" ${plan.errors.length?'disabled':''}>Revisar mi flow ${icon('arrow')}</button></div></section><div id="live-secondary">${secondaryKpis()}</div><div id="live-errors">${liveErrors()}</div><p class="projection-footnote">Proyección lineal · base ${CITY[city]} · ${month(config.historyStart)} — ${month(config.historyEnd)}.</p></div></div>`;}
function flowControls(){const last=latestBudget(),max=Math.max(100000000,Math.ceil(config.budget/10000000)*10000000);return `<aside class="panel flow-controls"><label class="field-label" for="budget">Presupuesto ${config.includesTax?'con IVA':'neto'}</label><div class="budget-input"><span>$</span><input id="budget" type="number" min="0" max="10000000000" step="100000" data-live-budget value="${config.budget||''}" placeholder="0" aria-label="Presupuesto en pesos colombianos"></div><input class="live-range budget-range" id="budget-range" type="range" min="0" max="${max}" step="100000" value="${config.budget}" aria-label="Ajustar presupuesto"><div class="range-caption"><span>COP</span><output id="budget-caption">${money(config.budget)}</output></div>${!config.budget&&last?`<button class="budget-suggestion" data-budget="${Math.round(last)}">Usar planeado de octubre ${money(last)}</button>`:''}<label class="field-label">Periodo de pauta</label><div class="control-dates"><label><span>Inicio</span><input type="date" data-config="startDate" value="${config.startDate}" aria-label="Inicio de pauta"></label><label><span>Fin</span><input type="date" data-config="endDate" value="${config.endDate}" aria-label="Fin de pauta"></label></div><span class="field-label">Medios</span><div class="channel-switches">${Object.entries(CHANNELS).map(([id,c])=>`<label><input type="checkbox" data-channel="${id}" ${config.channels.includes(id)?'checked':''}>${mark(id)}<span>${c.short}</span></label>`).join('')}</div><label class="field-label" for="history-window">Base histórica</label><select id="history-window" aria-label="Base histórica"><option value="quarter" ${config.historyStart==='2026-07'&&config.historyEnd==='2026-09'?'selected':''}>Jul – sep 2026</option><option value="last" ${config.historyStart==='2026-09'&&config.historyEnd==='2026-09'?'selected':''}>Septiembre 2026</option><option value="year" ${config.historyStart==='2026-02'&&config.historyEnd==='2026-09'?'selected':''}>Feb – sep 2026</option><option value="custom" ${!['2026-07:2026-09','2026-09:2026-09','2026-02:2026-09'].includes(config.historyStart+':'+config.historyEnd)?'selected':''}>Personalizada</option></select><div class="custom-history" ${!['2026-07:2026-09','2026-09:2026-09','2026-02:2026-09'].includes(config.historyStart+':'+config.historyEnd)?'':'hidden'}><label>Desde<input type="month" min="2025-02" max="2026-10" data-config="historyStart" value="${config.historyStart}"></label><label>Hasta<input type="month" min="2025-02" max="2026-10" data-config="historyEnd" value="${config.historyEnd}"></label></div><span class="field-label">Escenario <span class="muted">±${config.sensitivity}% CPL</span></span><div class="scenario-switch" role="group" aria-label="Escenario de CPL">${[['conservative','Conservador'],['base','Base'],['optimistic','Favorable']].map(([id,label])=>`<button data-scenario="${id}" class="${config.scenario===id?'active':''}" aria-pressed="${config.scenario===id}">${label}</button>`).join('')}</div><details class="advanced"><summary>Más ajustes ${icon('plus')}</summary><label class="field-label" for="plan-title">Nombre del flow</label><input id="plan-title" data-config="title" value="${esc(config.title)}" maxlength="100"><label class="field-label" for="frequency">Frecuencia social supuesta</label><input id="frequency" type="number" min="1" max="50" step="0.1" data-config="frequency" value="${config.frequency}"><label class="field-label" for="sensitivity">Variación de CPL (%)</label><input id="sensitivity" type="number" min="0" max="90" data-config="sensitivity" value="${config.sensitivity}"><label class="field-label" for="weighting">Peso de los meses</label><select id="weighting" data-config="weighting">${opts([['uniform','Mismo peso'],['recent','Mayor peso a los recientes']],config.weighting)}</select><label class="check tax-check"><input type="checkbox" data-config="includesTax" ${config.includesTax?'checked':''}>Presupuesto incluye IVA</label><label class="field-label" for="tax">IVA (%)</label><input id="tax" type="number" min="0" max="100" step="0.1" data-config="taxRate" value="${config.taxRate}"></details><button class="text-button change-projects" data-step="1">${icon('building')}${config.selected.length} proyectos · cambiar</button></aside>`;}
function allocationRows(){const projects=cityProjects().filter(p=>config.selected.includes(p.id));return projects.map(p=>{const budget=plan.rows.filter(r=>r.project.id===p.id).reduce((s,r)=>s+r.budget,0),share=plan.net?budget/plan.net*100:0;return `<div class="allocation-row" data-project-allocation="${p.id}"><img src="${esc(p.image||'./capital-logo.svg')}" alt=""><div class="allocation-project"><strong>${esc(p.name)}</strong><span>${esc(p.zone||REGION[city])}</span></div><div class="allocation-slider"><label for="weight-${p.id}">Peso <output data-allocation-share="${p.id}">${num(share,1)}%</output></label><input class="live-range" id="weight-${p.id}" type="range" min="0" max="100" step="1" data-live-weight="${p.id}" value="${config.allocation==='manual'?Number(config.priorities[p.id]??1):Math.max(1,Math.round(share))}" aria-label="Peso de inversión de ${esc(p.name)}"></div><output class="allocation-amount" data-allocation-amount="${p.id}">${money(budget)}</output></div>`;}).join('');}
function liveErrors(){return plan.errors.length?`<div class="input-errors" role="alert">${plan.errors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>`:plan.unallocated?`<div class="quality-note">${money(plan.unallocated)} pendientes de asignar.</div>`:'';}

function planKpis(){const valid=!plan.errors.length;return `<div class="metrics plan-metrics">${[['calendar','Inversión diaria',valid?money(plan.daily):'—','COP / día'],['building','Leads estimados',valid?num(plan.results):'—','Incluye conversiones atribuidas'],['flow','CPL proyectado',valid?money(plan.cpl):'—','COP / resultado'],['grid','Impresiones estimadas',valid?num(plan.impressions):'—',plan.impressionsComplete?'Total del plan':'Base disponible'],['arrow','Clics estimados',valid?num(plan.clicks):'—',plan.clicksComplete?'Total del plan':'Base disponible']].map(([ic,label,value,note],i)=>`<article class="metric"><span class="metric-icon ${i%2?'blue':'yellow'}">${icon(ic)}</span><div><span>${label}</span><strong>${value}</strong><small>${note}</small></div></article>`).join('')}</div>`;}
function secondaryKpis(){const valid=!plan.errors.length,reachRows=plan.rows.filter(r=>r.channel!=='google'&&r.reach!==null),reach=reachRows.reduce((s,r)=>s+r.reach,0);return `<div class="secondary-metrics"><div><span>Alcance social modelado*</span><strong>${valid&&reachRows.length?num(reach):'—'}</strong></div><div><span>CPM proyectado</span><strong>${valid&&plan.impressions?money(plan.allocated/plan.impressions*1000):'—'}</strong></div><div><span>CPC proyectado</span><strong>${valid&&plan.clicks?money(plan.allocated/plan.clicks):'—'}</strong></div><div><span>CTR proyectado</span><strong>${valid&&plan.impressions?pct(plan.clicks/plan.impressions):'—'}</strong></div><div><span>Inversión asignada</span><strong>${money(plan.allocated)}</strong></div></div><p class="projection-footnote">* Suma de alcances modelados por campaña, sin desduplicar. Frecuencia ${num(plan.frequency,1)}. Google: no disponible.</p>`;}

function flowTable(){return `<div class="table-scroll"><table class="flow-table"><thead><tr><th>Proyecto</th><th>Medio</th><th>Inversión</th><th>CPL editable</th><th>Leads / conv.</th><th>Impresiones</th><th>Alcance*</th><th></th></tr></thead><tbody>${plan.rows.map(r=>`<tr data-flow-row="${r.id}"><td><div class="project-cell">${r.project.image?`<img src="${esc(r.project.image)}" alt="">`:''}<div><strong>${esc(r.project.name)}</strong><small class="basis ${r.rate.basis}">${r.manual?'CPL manual':r.rate.basis==='own'?'Histórico propio':'Referencia de ciudad'}</small></div></div></td><td><span class="medium-cell">${mark(r.channel)}${CHANNELS[r.channel].short}</span></td><td class="value" data-row-budget>${money(r.budget)}</td><td><div class="cpl-field"><input type="number" min="1" step="100" value="${Math.round(r.baseCpl)}" data-cpl="${r.id}" aria-label="CPL base de ${esc(r.project.name)} en ${CHANNELS[r.channel].short}"><button data-reset="${r.id}" ${r.manual?'':'hidden'} aria-label="Restaurar CPL histórico de ${esc(r.project.name)}">↺</button></div><small class="scenario-cpl" data-row-cpl>${plan.scenarioFactor!==1?'Aplicado: '+money(r.cpl):'COP'}</small></td><td class="result-value" data-row-results>${num(r.results)}</td><td data-row-impressions>${num(r.impressions)}</td><td data-row-reach>${r.reach===null?'—':num(r.reach)+'*'}</td><td><button class="icon-button" data-detail="${r.id}" aria-label="Ver gasto diario, clics y fuente de ${esc(r.project.name)} en ${CHANNELS[r.channel].short}">${icon('info')}</button></td></tr>`).join('')}</tbody><tfoot><tr><td colspan="2">Total ${CITY[city]}</td><td data-total-budget>${money(plan.allocated)}</td><td data-total-cpl>${money(plan.cpl)}</td><td data-total-results>${num(plan.results)}</td><td data-total-impressions>${plan.impressionsComplete?num(plan.impressions):'Parcial'}</td><td>Sin desduplicar</td><td></td></tr></tfoot></table>${!plan.rows.length?`<div class="table-empty">Completa los controles para ver tu plan.</div>`:''}</div>`;}

function flowView(){return `<div class="flow-workspace">${flowControls()}<div class="flow-main"><div id="live-kpis">${planKpis()}</div><section class="panel table-panel"><div class="panel-head"><div><h2>Plan por proyecto y medio</h2><p>Modifica el CPL para explorar el resultado.</p></div><button class="icon-button" data-step="2" aria-label="Editar reparto entre proyectos">${icon('flow')}</button></div><div id="live-table">${flowTable()}</div><div class="table-bottom"><span id="campaign-count">${plan.rows.length} campañas · ${config.selected.length} proyectos</span><button class="text-button" data-action="print">${icon('download')}PDF</button></div></section><div id="live-naming">${namingPreview()}</div><div id="live-secondary">${secondaryKpis()}</div><div id="live-errors">${liveErrors()}</div>${plan.warnings.length?`<details class="warnings"><summary>${icon('info')}${plan.warnings.length} observaciones de la base</summary><ul>${plan.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></details>`:''}<p class="projection-footnote">Resultados estimados = inversión ÷ CPL · gasto diario = inversión ÷ ${plan.days} días. No equivalen a compradores ni personas únicas.</p></div></div>`;}
function namingPreview(){const r=plan.rows.find(r=>r.project.id==='BTA-VERDI'&&r.channel==='meta')||plan.rows[0];return `<section class="panel naming-preview">${icon('code')}<div><strong>Nomenclatura de campaña</strong><span>Variables del flow + patrón histórico.</span></div><code>${r?esc(r.naming.name):'Selecciona proyectos para generar los nombres'}</code><button class="button" data-view="names">Ver nomenclaturas ${icon('arrow')}</button></section>`;}

function builderView(){return `${flowHero()}<div class="workspace-surface">${stepper()}${step===1?selectionView():step===2?budgetView():flowView()}</div>`;}

function historyTable(rows){if(!rows.length)return empty('Sin registros con estos filtros','Cambia el periodo, medio o proyecto.');if(historyTab==='months'){return `<table><thead><tr><th>Periodo</th><th>Planeada</th><th>Real registrada</th><th>Ejecución</th><th>Leads / conv.</th><th>CPL de leads</th><th>Filas</th></tr></thead><tbody>${historicalSeries(rows).map(s=>`<tr><td><strong>${month(s.month)}</strong>${s.month==='2026-10'?'<span class="pill partial">Al 19 oct</span>':''}</td><td>${money(s.planned)}</td><td class="value">${money(s.actual)}</td><td>${pct(s.execution)}</td><td>${num(s.leads,1)}</td><td>${money(s.cpl)}</td><td>${s.rows}</td></tr>`).join('')}</tbody></table>`;}
  if(historyTab==='projects'){const keys=[...new Set(rows.map(r=>r[2]||r[3]))];return `<table><thead><tr><th>Proyecto / iniciativa</th><th>Planeada</th><th>Real registrada</th><th>Leads / conv.</th><th>CPL de leads</th><th>Meses</th></tr></thead><tbody>${keys.map(key=>{const group=rows.filter(r=>(r[2]||r[3])===key),s=summarizeLedger(group),p=data.projects.find(p=>p.id===key);return {s,label:p?.name||key};}).sort((a,b)=>b.s.actual-a.s.actual).map(({s,label})=>`<tr><td><strong>${esc(label)}</strong></td><td>${money(s.planned)}</td><td class="value">${money(s.actual)}</td><td>${num(s.leads,1)}</td><td>${money(s.cpl)}</td><td>${s.months}</td></tr>`).join('')}</tbody></table>`;}
  return `<table class="ledger-table"><thead><tr><th>Mes / fuente</th><th>Campaña</th><th>Medio</th><th>Planeada S</th><th>Real V</th><th>Resultado Z</th></tr></thead><tbody>${rows.slice(0,200).map(r=>`<tr><td><strong>${month(r[1])}</strong><span class="cell-sub">Fila ${r[14]}</span></td><td><div class="campaign-cell"><strong>${esc(data.projects.find(p=>p.id===r[2])?.name||r[3])}</strong><code>${esc(r[5])}</code>${r[15].includes('repeated-metrics')?'<span class="pill partial">Métricas repetidas en la fuente</span>':''}${r[15].includes('conflicting-kpi')?'<span class="pill partial">KPI incoherente · fuera del CPL</span>':''}</div></td><td>${MEDIA[r[4]].short}</td><td>${money(r[6])}</td><td class="value">${money(r[7])}</td><td>${num(r[8],1)}<span class="cell-sub">${esc(r[16]||'Sin KPI')}</span></td></tr>`).join('')}</tbody></table>${rows.length>200?`<p class="table-limit">Mostrando 200 de ${num(rows.length)} filas. Usa la búsqueda para acotar o descarga el detalle completo.</p>`:''}`;
}
function historyView(){const rows=historyRows(true),s=summarizeLedger(rows);return `${pageHead(`${REGION[city].toUpperCase()} / DATOS DE ORIGEN`,'El histórico, sin perder el detalle.','Planeación y ejecución del consolidado. La selección del nuevo flow no cambia estos totales.',`<button class="button dark" data-action="export-history">${icon('download')}Descargar detalle</button>`)}${periodBar()}<div class="history-filters"><select id="history-channel" aria-label="Medio del histórico">${opts([['all','Todos los medios'],...Object.entries(MEDIA).map(([id,c])=>[id,c.name])],historyChannel)}</select><select id="history-project" aria-label="Proyecto del histórico">${opts([['all','Todos los proyectos e iniciativas'],...cityProjects().map(p=>[p.id,p.name])],historyProject)}</select><label class="search-field">${icon('search')}<input id="history-search" value="${esc(historySearch)}" placeholder="Buscar iniciativa o campaña" aria-label="Buscar en el histórico"></label></div><div class="scope-line"><span>${rangeLabel()}</span><strong>${historyChannel==='all'&&historyProject==='all'&&!historySearch?'Consolidado completo':'Vista filtrada'} de ${CITY[city]}</strong></div>${historicalKpis(s,rows)}<section class="panel table-panel"><div class="panel-head"><div class="table-tabs">${[['months','Por mes'],['projects','Por proyecto'],['campaigns','Campañas y filas fuente']].map(([id,label])=>`<button data-history-tab="${id}" class="${historyTab===id?'active':''}">${label}</button>`).join('')}</div><span class="muted">${num(rows.length)} filas</span></div><div class="table-scroll">${historyTable(rows)}</div></section>${sourceNote(rows)}${s.flagged?`<div class="quality-note">${icon('info')}<p>${s.flagged} filas tienen métricas idénticas a otra campaña con el mismo nombre y mes. Se mantienen como aparecen en Excel para conciliar; puedes identificarlas en el detalle de campañas.</p></div>`:''}`;}
function namesView(){return `${pageHead(`${REGION[city].toUpperCase()} / NOMENCLATURAS`,'Cada campaña, con su nombre.','Patrones del archivo original, conectados a los proyectos de tu flow.',plan.rows.length?`<button class="button dark" data-action="copy-all">${icon('copy')}Copiar todas</button>`:'')}${!plan.rows.length?`${empty('Primero crea tu flow','Elige los proyectos y define el presupuesto para generar las nomenclaturas.')}<button class="button dark" data-new-flow>Crear flow ${icon('arrow')}</button>`:`<section class="panel naming-settings"><div><label class="field-label" for="naming-mode">Nomenclatura</label><select id="naming-mode" data-config="namingMode">${opts([['new','Nueva · trimestre del flow'],['existing','Conservar la existente']],config.namingMode)}</select></div><div><label class="field-label" for="stage">Etapa</label><select id="stage" data-config="stage">${opts([['auto','Respetar la etapa existente'],['LAN','Lanzamiento'],['POSTLAN','Postlanzamiento'],['SOS','Sostenimiento']],config.stage)}</select></div><div><label class="field-label" for="suffix">Sufijo opcional</label><input id="suffix" maxlength="30" data-config="suffix" value="${esc(config.suffix)}" placeholder="Ej. NOVIEMBRE"></div></section><div class="naming-guide"><span>MEDIO</span> / <span>TIPO</span> / <span>PROYECTO</span> / <span>ETAPA</span> / <span>OBJETIVO</span> / <span>AUDIENCIA</span> / <span>CIUDAD</span> / <span>FORMATO</span> / <span>TRIMESTRE</span></div><div class="names-list">${plan.rows.map(r=>`<article class="panel name-card"><div class="name-head">${mark(r.channel)}<div><strong>${esc(r.project.name)}</strong><span>${CHANNELS[r.channel].name} · ${CITY[city]}</span></div><span class="pill">${r.naming.generated?'Propuesta':'Existente'}</span></div><div class="name-code"><code>${esc(r.naming.name)}</code><button class="button" data-copy="${esc(r.naming.name)}">${icon('copy')}Copiar</button></div><p>Patrón: ${esc(r.naming.source)}${r.naming.row?` · fila ${r.naming.row}`:''}</p></article>`).join('')}</div>`}`;}
function methodView(){const sources=data.meta.consolidated;return `${pageHead('TRAZABILIDAD / METODOLOGÍA','Cifras que puedes revisar.','El histórico refleja los consolidados de cada ciudad. La proyección utiliza sus campañas de leads.')}<section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">CONTROL CONTRA EXCEL · TODO EL HISTÓRICO</span><h2>Dos ciudades. Dos fuentes.</h2></div></div><div class="table-scroll"><table><thead><tr><th>Ciudad / hoja</th><th>Filas de detalle</th><th>Inversión planeada · S</th><th>Inversión real · V</th></tr></thead><tbody>${Object.entries(sources).map(([c,s])=>`<tr><td><strong>${CITY[c]}</strong><span class="cell-sub">${esc(s.sheet.trim())}</span></td><td>${num(s.rows)}<span class="cell-sub">Entre filas ${s.firstRow} y ${s.lastRow}</span></td><td>${money(s.planned)}</td><td class="value">${money(s.actual)}</td></tr>`).join('')}</tbody></table></div><p class="table-note">Febrero–diciembre 2025 y febrero–octubre 2026 · corte 19 de octubre. Los subtotales y las hojas “Copia de” no se vuelven a sumar.</p></section><div class="method-grid">${[['01','Inversión real','Σ columna V','Se suman todas las filas de detalle de la ciudad y el periodo: incluye marca, otros medios e iniciativas sin proyecto reconocido.'],['02','CPL de leads','Σ inversión de leads ÷ Σ leads','Solo filas con KPI de leads coherente. El gasto de marca permanece en inversión total, pero no entra en el CPL de performance.'],['03','Proyección','Presupuesto asignado ÷ CPL base','El CPL usa el proyecto y medio seleccionados. Si falta histórico propio, se informa la referencia de igual ciudad y tipología.'],['04','Impresiones y clics','Inversión ÷ CPM × 1.000 · CTR','CPM = gasto / impresiones × 1.000. CTR = clics / impresiones. Alcance social = impresiones / frecuencia supuesta, sin desduplicación.']].map(([n,title,formula,copy])=>`<article class="panel formula-card"><span>${n}</span><h3>${title}</h3><div class="formula">${formula}</div><p>${copy}</p></article>`).join('')}</div><section class="panel methodology"><h2>Qué está incluido y cómo leerlo</h2>${data.meta.notes.map(n=>`<p>${icon('check')}<span>${esc(n)}</span></p>`).join('')}<p>${icon('info')}<span>La ponderación reciente asigna pesos 1, 2, … al intervalo elegido y calcula la razón de sumas ponderadas. Esos pesos solo afectan la proyección; nunca los totales del histórico.</span></p><p>${icon('info')}<span>El presupuesto se distribuye por pesos y se reconcilia al peso colombiano. Una base de CPL insuficiente deja inversión pendiente de asignar. Los escenarios ±${config.sensitivity}% son sensibilidades editables, no intervalos de confianza.</span></p></section>`;}
function savedFlows(){try{return JSON.parse(localStorage.getItem('capital-flows-v2')||'[]');}catch{return [];}}
function savedView(){const flows=savedFlows().map((x,index)=>({...x,index})).filter(x=>x.config.city===city);return `${pageHead(`${REGION[city].toUpperCase()} / MIS PLANES`,'Tus flows, a mano.','Borradores guardados en este navegador. Puedes llevarlos a otro equipo con un archivo JSON.')}<div class="saved-actions"><button class="button dark" data-action="save">${icon('save')}Guardar flow actual</button><button class="button" data-action="export-config">${icon('download')}Exportar configuración</button><label class="button">Importar configuración<input id="config-file" type="file" accept=".json" hidden></label></div><div class="saved-grid">${flows.map(f=>`<article class="panel saved-card"><span class="eyebrow">${CITY[city]} · ${new Date(f.savedAt).toLocaleDateString('es-CO')}</span><h2>${esc(f.config.title)}</h2><strong>${money(f.config.budget)}</strong><p>${f.config.selected.length} proyectos · ${f.config.startDate} → ${f.config.endDate}</p><div><button class="button dark" data-load="${f.index}">Abrir flow ${icon('arrow')}</button><button class="text-button muted" data-delete="${f.index}">Eliminar</button></div></article>`).join('')}</div>${flows.length?'':empty('Todavía no tienes flows guardados en '+CITY[city],'Guarda el plan actual o importa una configuración.')}`;}

function render(){plan=buildPlan(data,config);document.documentElement.dataset.city=city;document.documentElement.dataset.view=view;$('#app').innerHTML=`${header()}<main id="main">${({summary:summaryView,builder:builderView,history:historyView,names:namesView,method:methodView,saved:savedView})[view]()}</main><footer class="footer"><span>CAPITAL <b>flow.</b> <span>Hecho para planear mejor.</span></span><div>${CITY[city]} · Datos del archivo al 19 oct 2026 <i>·</i> ${localReady?'Borrador local':'Guardado local no disponible'}</div></footer>`;bind();bindLiveControls();document.querySelectorAll('.project-image img').forEach(img=>img.onerror=()=>{img.parentNode.classList.add('image-error');img.remove();});}
function showDetail(id){const r=plan.rows.find(r=>r.id===id);if(!r)return;const sources=data.ledger.filter(x=>x[2]===r.project.id&&x[4]===r.channel&&x[1]>=config.historyStart&&x[1]<=config.historyEnd&&x[9]!==null),dialog=$('#detail-dialog');$('#dialog-content').innerHTML=`<button class="dialog-close icon-button" id="close-dialog" aria-label="Cerrar">${icon('close')}</button><span class="eyebrow">${CHANNELS[r.channel].name} / ${CITY[city]}</span><h2 id="detail-title">${esc(r.project.name)}</h2><p>${r.rate.basisLabel} · ${month(config.historyStart)} — ${month(config.historyEnd)}</p><div class="detail-formula"><strong>${money(r.budget)}</strong><span>÷ ${money(r.cpl)} CPL</span><b>${num(r.results,1)} resultados estimados</b></div><div class="detail-stats"><div><span>Inversión real de la referencia</span><strong>${money(r.rate.raw.spend)}</strong></div><div><span>Leads de la referencia</span><strong>${num(r.rate.raw.results,1)}</strong></div><div><span>CPL base ${r.manual?'manual':'calculado'}</span><strong>${money(r.baseCpl)}</strong></div><div><span>Alcance modelado</span><strong>${num(r.reach)}</strong></div><div><span>Gasto diario</span><strong>${money(r.daily)}</strong></div><div><span>Clics estimados</span><strong>${num(r.clicks)}</strong></div><div><span>Impresiones estimadas</span><strong>${num(r.impressions)}</strong></div><div><span>CPM proyectado</span><strong>${r.impressions?money(r.budget/r.impressions*1000):'—'}</strong></div></div><p>${r.rate.basis==='own'?`${sources.length} filas de ${esc(data.meta.consolidated[city].sheet.trim())}.`:'Referencia de otros proyectos de la misma ciudad y tipología.'} ${config.weighting==='recent'?'Se aplican pesos crecientes por mes al calcular el CPL.':'CPL = suma de gasto / suma de leads.'}</p><p class="muted">${r.reach===null?'No se modela alcance de Google.':'Alcance = impresiones / '+plan.frequency+'. Es una aproximación sin desduplicación.'}</p><code class="detail-code">${esc(r.naming.name)}</code>`;$('#close-dialog').onclick=()=>dialog.close();dialog.showModal();}
function exportHistory(){const rows=historyRows(true),sheet=data.meta.consolidated[city].sheet.trim();download(csvText([['Ciudad','Mes','Proyecto/iniciativa','Medio','Nomenclatura','Inversión planeada S COP','Inversión real V COP','Resultado Z','Leads elegibles','Inversión de leads COP','Impresiones AQ','Clics AR','Leads planeados AF','Hoja','Fila','Observaciones','KPI X'],...rows.map(r=>[CITY[r[0]],r[1],data.projects.find(p=>p.id===r[2])?.name||r[3],MEDIA[r[4]].name,r[5],...r.slice(6,14),sheet,r[14],r[15].join(' | '),r[16]])]),`capital_${city.toLowerCase()}_consolidado_${period.start}_${period.end}.csv`);}
function bind(){
  document.querySelectorAll('[data-open-projects]').forEach(b=>b.onclick=()=>{step=1;nav('builder');});
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>nav(b.dataset.view));
  document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>switchCity(b.dataset.city));
  document.querySelectorAll('[data-new-flow]').forEach(b=>b.onclick=()=>{step=1;nav('builder');});
  document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const next=Number(b.dataset.step);if(next>1&&!config.selected.length){toast('Selecciona al menos un proyecto.');return;}if(next===3&&plan.errors.length){toast('Completa el presupuesto y las fechas.');step=2;}else step=next;view='builder';location.hash='builder';render();window.scrollTo({top:0,behavior:'smooth'});});
  document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=({all:{start:'2025-02',end:'2026-10'},'2026':{start:'2026-02',end:'2026-10'},'2025':{start:'2025-02',end:'2025-12'},last:{start:'2026-09',end:'2026-09'}})[b.dataset.period];render();});
  document.querySelectorAll('[data-period-field]').forEach(el=>el.onchange=()=>{const next={...period,[el.dataset.periodField]:el.value};if(!/^\d{4}-\d{2}$/.test(el.value)||next.start>next.end){toast('Revisa el intervalo histórico.');render();return;}period=next;render();});
  document.querySelectorAll('[data-config]').forEach(el=>el.onchange=()=>{const value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(el.type==='number'&&(!Number.isFinite(value)||value<Number(el.min||0)||(el.max&&value>Number(el.max)))){toast('Revisa el valor ingresado.');render();return;}update({[el.dataset.config]:value});});
  document.querySelectorAll('[data-channel]').forEach(el=>el.onchange=()=>update({channels:el.checked?[...config.channels,el.dataset.channel]:config.channels.filter(c=>c!==el.dataset.channel)}));
  document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{const id=b.dataset.project;if(!cityProjects().some(p=>p.id===id))return;update({selected:config.selected.includes(id)?config.selected.filter(p=>p!==id):[...config.selected,id]});});
  document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{filter.kind=b.dataset.kind;render();});
  document.querySelectorAll('[data-budget]').forEach(b=>b.onclick=()=>update({budget:Number(b.dataset.budget)}));
  document.querySelectorAll('[data-weight]').forEach(el=>el.onchange=()=>{const v=Number(el.value);if(!Number.isFinite(v)||v<0)return;update({priorities:{...config.priorities,[el.dataset.weight]:v}});});
  document.querySelectorAll('[data-cpl]').forEach(el=>el.onchange=()=>{const v=Number(el.value);if(!(v>0)||!Number.isFinite(v)){toast('El CPL debe ser mayor que cero.');render();return;}update({overrides:{...config.overrides,[el.dataset.cpl]:v}});});
  document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{delete config.overrides[b.dataset.reset];update({});});
  document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>update({scenario:b.dataset.scenario}));
  document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>showDetail(b.dataset.detail));
  document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copy(b.dataset.copy));
  document.querySelectorAll('[data-history-tab]').forEach(b=>b.onclick=()=>{historyTab=b.dataset.historyTab;render();});
  for(const [id,read,write] of [['project-search',()=>filter.search,v=>filter.search=v],['history-search',()=>historySearch,v=>historySearch=v]]){const el=$('#'+id);if(el)el.oninput=()=>{write(el.value);clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const cursor=el.selectionStart;render();const next=$('#'+id);if(next){next.focus();next.setSelectionRange(cursor??read().length,cursor??read().length);}},200);};}
  if($('#active-filter'))$('#active-filter').onchange=e=>{filter.active=e.target.checked;render();};
  if($('#selected-filter'))$('#selected-filter').onchange=e=>{filter.selected=e.target.checked;render();};
  if($('#history-channel'))$('#history-channel').onchange=e=>{historyChannel=e.target.value;render();};
  if($('#history-project'))$('#history-project').onchange=e=>{historyProject=e.target.value;render();};
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;
    if(a==='example'){loadExample();return;}
    if(a==='select-visible')update({selected:[...new Set([...config.selected,...visibleProjects().map(p=>p.id)])]});
    if(a==='clear')update({selected:[]});
    if(a==='export'&&!plan.errors.length&&plan.rows.length)download(flowExport(plan,config),normalize(config.title).toLowerCase()+'.csv');
    if(a==='print')window.print();
    if(a==='copy-all')copy(plan.rows.map(r=>r.naming.name).join('\n'));
    if(a==='save'){try{const flows=savedFlows();flows.unshift({savedAt:new Date().toISOString(),config:structuredClone(config)});localStorage.setItem('capital-flows-v2',JSON.stringify(flows.slice(0,60)));toast('Flow de '+CITY[city]+' guardado.');if(view==='saved')render();}catch{toast('No se pudo guardar. Exporta la configuración.');}}
    if(a==='export-config')download(JSON.stringify({schema:'capital-flow-v2',config},null,2),normalize(config.title).toLowerCase()+'.json','application/json');
    if(a==='export-history')exportHistory();
  });
  document.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{const saved=savedFlows()[Number(b.dataset.load)];config=sanitize(saved.config,city);persist();step=3;nav('builder');});
  document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{try{const flows=savedFlows();flows.splice(Number(b.dataset.delete),1);localStorage.setItem('capital-flows-v2',JSON.stringify(flows));render();toast('Flow eliminado.');}catch{toast('No se pudo eliminar el borrador.');}});
  if($('#config-file'))$('#config-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('El archivo supera 1 MB.');const j=JSON.parse(await file.text()),input=j.config||j;if(!Array.isArray(input.selected)||!Array.isArray(input.channels))throw Error('Configuración no válida.');const target=input.city||input.selected[0]?.slice(0,3)||city;if(!CITY[target])throw Error('Ciudad no válida.');const next=sanitize(input,target);persist();city=target;config=next;persist();step=2;nav('builder');toast('Configuración importada para '+CITY[city]+'.');}catch(error){toast(error.message);}};
}

function loadExample(){config={...defaultConfig(city),budget:city==='BTA'?30000000:15000000,allocation:'equal',selected:city==='BTA'?['BTA-ELEMENT142','BTA-NUVO','BTA-MISTRAL','BTA-VERDI']:['MDE-PUERTOCAPRI'],example:true};persist();step=3;nav('builder');toast('Simulación de ejemplo cargada para '+CITY[city]+'.');}
function refreshLive(source){
  plan=buildPlan(data,config);persist();
  for(const [id,html] of [['live-kpis',planKpis()],['live-secondary',secondaryKpis()],['live-errors',liveErrors()]]){const el=$('#'+id);if(el)el.innerHTML=html;}
  if($('#live-naming')){$('#live-naming').innerHTML=namingPreview();const namesButton=$('#live-naming [data-view]');if(namesButton)namesButton.onclick=()=>nav('names');}
  if(source!=='cpl'&&$('#live-table')){$('#live-table').innerHTML=flowTable();bindFlowRows();}
  if(source==='cpl'){
    for(const r of plan.rows){const row=document.querySelector(`[data-flow-row="${r.id}"]`);if(!row)continue;for(const [key,value] of [['budget',money(r.budget)],['results',num(r.results)],['impressions',num(r.impressions)],['reach',r.reach===null?'—':num(r.reach)+'*'],['cpl',plan.scenarioFactor!==1?'Aplicado: '+money(r.cpl):'COP']])row.querySelector('[data-row-'+key+']').textContent=value;row.querySelector('.basis').textContent=r.manual?'CPL manual':r.rate.basis==='own'?'Histórico propio':'Referencia de ciudad';row.querySelector('[data-reset]').hidden=!r.manual;}
    for(const [key,value] of [['budget',money(plan.allocated)],['cpl',money(plan.cpl)],['results',num(plan.results)],['impressions',plan.impressionsComplete?num(plan.impressions):'Parcial']]){const el=document.querySelector('[data-total-'+key+']');if(el)el.textContent=value;}
  }
  for(const p of cityProjects().filter(p=>config.selected.includes(p.id))){const value=plan.rows.filter(r=>r.project.id===p.id).reduce((s,r)=>s+r.budget,0);const amount=document.querySelector(`[data-allocation-amount="${p.id}"]`),share=document.querySelector(`[data-allocation-share="${p.id}"]`);if(amount)amount.textContent=money(value);if(share)share.textContent=pct(plan.net?value/plan.net:0);}
  if($('#budget-caption'))$('#budget-caption').textContent=money(config.budget);
  if($('#campaign-count'))$('#campaign-count').textContent=plan.rows.length+' campañas · '+config.selected.length+' proyectos';
  document.querySelectorAll('[data-export-button],#generate-flow').forEach(b=>b.disabled=Boolean(plan.errors.length));
  const allocation=document.querySelector('[data-config="allocation"]');if(allocation)allocation.value=config.allocation;
  clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const status=$('#live-status');if(status)status.textContent=plan.errors.length?plan.errors.join(' '):num(plan.results)+' resultados estimados, CPL '+money(plan.cpl);},250);
}
function bindFlowRows(){
  document.querySelectorAll('[data-cpl]').forEach(el=>{
    el.oninput=()=>{const v=Number(el.value);if(v>0&&Number.isFinite(v)){el.setCustomValidity('');config.overrides={...config.overrides,[el.dataset.cpl]:v};refreshLive('cpl');}else {el.setCustomValidity('Ingresa un CPL mayor que cero.');document.querySelectorAll('[data-export-button]').forEach(b=>b.disabled=true);const errors=$('#live-errors');if(errors)errors.innerHTML='<div class="input-errors" role="alert">Ingresa un CPL mayor que cero para recalcular y exportar.</div>';}};
    el.onchange=()=>{const v=Number(el.value);if(!(v>0)||!Number.isFinite(v)){toast('El CPL debe ser mayor que cero.');render();return;}config.overrides={...config.overrides,[el.dataset.cpl]:v};render();persist();};
  });
  document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>showDetail(b.dataset.detail));
  document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{delete config.overrides[b.dataset.reset];update({});});
}
function bindLiveControls(){
  const budget=$('[data-live-budget]'),range=$('#budget-range');
  if(budget)budget.oninput=()=>{const v=Number(budget.value);if(!Number.isFinite(v)||v<0||v>10000000000){budget.setCustomValidity('Revisa el presupuesto.');return;}budget.setCustomValidity('');config.budget=v;if(range){range.max=Math.max(100000000,Math.ceil(v/10000000)*10000000);range.value=v;}refreshLive('budget');};
  if(range)range.oninput=()=>{config.budget=Number(range.value);if(budget)budget.value=config.budget;refreshLive('budget');};
  document.querySelectorAll('[data-live-weight]').forEach(el=>el.oninput=()=>{if(config.allocation!=='manual'){config.priorities=Object.fromEntries(cityProjects().filter(p=>config.selected.includes(p.id)).map(p=>[p.id,Math.max(1,Math.round(plan.rows.filter(r=>r.project.id===p.id).reduce((s,r)=>s+r.budget,0)/(plan.net||1)*100))]));}config.allocation='manual';config.priorities[el.dataset.liveWeight]=Number(el.value);refreshLive('weights');});
  const history=$('#history-window');if(history)history.onchange=()=>{if(history.value==='custom'){const fields=$('.custom-history');if(fields)fields.hidden=false;return;}const ranges={quarter:['2026-07','2026-09'],last:['2026-09','2026-09'],year:['2026-02','2026-09']};const [historyStart,historyEnd]=ranges[history.value];update({historyStart,historyEnd});};
  bindFlowRows();
}

window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(views.includes(next)&&view!==next){view=next;render();}});
try{const response=await fetch('./data.json');if(!response.ok)throw Error('No fue posible abrir los consolidados.');data=await response.json();const localImages=['BTA-ELEMENT142','BTA-NUVO','BTA-MISTRAL','BTA-VERDI','MDE-PUERTOCAPRI'];data.projects.forEach(p=>{if(localImages.includes(p.id))p.image='./projects/'+p.id.toLowerCase()+'.webp';});try{config=sanitize(cityDrafts[city],city);}catch{config=defaultConfig(city);}render();}catch(error){$('#app').innerHTML=`<div class="loading"><h1>No pudimos cargar el histórico.</h1><p>${esc(error.message)}</p><button class="button dark" onclick="location.reload()">Volver a intentar</button></div>`;}
